"""LaTeX printer. Spacing uses a single space, the
LaTeX convention here (e.g. 'A B' for a product, 'A + B' for a sum)."""
from .printer import Printer


class LatexPrinter(Printer):
    def _print_MatrixSymbol(self, expr):
        return expr.name

    def _print__Coeff(self, expr):
        return str(expr.value)

    def _print_MatMul(self, expr):
        coeff, rest = expr.as_coeff_mmul()
        if coeff < 0:
            body = " ".join(self._print(arg) for arg in rest.args)
            return "-" + body
        return " ".join(self._print(arg) for arg in expr.args)

    def _print_MatAdd(self, expr):
        parts = []
        for i, arg in enumerate(expr.args):
            term = self._print(arg)
            if i == 0:
                parts.append(term)
            elif term.startswith("-"):
                parts.append(" - " + term[1:])
            else:
                parts.append(" + " + term)
        return "".join(parts)


def latex(expr):
    return LatexPrinter().doprint(expr)

